#!/bin/bash
set -euo pipefail

SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)
CIMGUI_DIR=${1:?Path to the pinned cimgui checkout is required}
CIMGUI_DIR=$(cd -- "${CIMGUI_DIR}" && pwd)
CIMGUI_REVISION="c4461a7eadbd17b6a6a8124a8abbf499aba6318d"
if [ "$(git -C "${CIMGUI_DIR}" rev-parse HEAD)" != "${CIMGUI_REVISION}" ]; then
    echo "Expected cimgui ${CIMGUI_REVISION}" >&2
    exit 1
fi

pushd "${CIMGUI_DIR}/generator" > /dev/null
# IMGUI_PATH avoids replacing the cimgui checkout's imgui submodule.
IMGUI_PATH="${SCRIPT_DIR}/imgui" luajit "${SCRIPT_DIR}/../generate-cimgui.lua" \
    "${CIMGUI_COMPILER:-gcc}" "freetype" -DIMGUI_USE_WCHAR32
popd > /dev/null

cp "${CIMGUI_DIR}"/cimgui.{h,cpp} "${SCRIPT_DIR}/"
for metadata in definitions structs_and_enums typedefs_dict; do
    cp "${CIMGUI_DIR}/generator/output/${metadata}."{json,lua} "${SCRIPT_DIR}/"
done
cp "${CIMGUI_DIR}/generator/output/overloads.txt" "${SCRIPT_DIR}/"
printf 'Generated by cimgui version %s\n' "${CIMGUI_REVISION}" > "${SCRIPT_DIR}/VERSION.txt"
